INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('1adbaea5-8719-441d-83e8-65633c13b236', 'Muzaffer', '#1 sipariş restorana iletildi, restoranda ürünün tamamı yada kısmi olara bulunmuyor buradaki süreç nedir', '"2026-06-23T09:34:54.367Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('6721db50-52f0-45ee-938e-90ced203122b', 'Muzaffer', '#2 sipariş bize uygulama üzerinden geldi, sipariş restorana ve fiyua iletildi , her ikişsine de iletildiğini nasıl kontrol ediyoruz, onay mekanizması var mı, restoran onayladı, fiyuu onaylamadı, buradaki süreç nedir', '"2026-06-23T09:38:54.033Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('0bce4fd7-55db-47a4-a47f-40ad1c999138', 'Muzaffer', '#2 restoran kuryenin ne zaman geleceğini yaklaşık olarak da olsa görebiliyor mu? restoran siparişi ne zaman hazırlamalı.', '"2026-06-23T09:40:48.729Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('4a20cf2b-1e0d-4d72-a49f-2963c95bfad7', 'Muzaffer', '#2 platform kuryesi çok geç geldi, müşteri gecikme nedeniyle siparişini iptal etmek istiyor, restoran siparişi hazırlamış burada hareket adımları nedir?', '"2026-06-23T09:44:13.266Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('7e8ba574-23cc-4ac9-9dd1-d4adaa75c8b7', 'Muzaffer', '#2 sipariş müşteriye ulaştı, müşteri ürünün eksik olduğunu iddia ediyor,  daha doğrusu bu iddiayı kime iletiyor, bize mi restorana mı?  burada bir kaç soru var, 1-restoran eksik olduğunu kabul etmiyor, tam verdim diyor 2- kuryenin ürünü alırken kontrol ederekmi alıyor 3- müşteri bu iddiasını nasıl kanıtlıyor', '"2026-06-23T10:24:45.913Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('bb98c006-a461-42cf-b65b-07a340f8e145', 'Muzaffer', '#2 sipariş müşteriye ulaştı, eksik, restoran da eksik olduğunu kabul ediyor, bu durumda ne yapıyoruz', '"2026-06-23T10:25:58.860Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('15e48ac7-9c05-43a3-9bd1-a940102b4d24', 'Muzaffer', '#4 sipariş geldi , bağımsız kuryeyi yönlendirdik, kurye ürünü aldı, müşteriye götürmedi, telefonları açmıyor, müşteri arıyor ürün nerede diye restoran arıyor ürün nerede diye. bu durumdaki hareket nedir', '"2026-06-23T10:28:10.023Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('a1cf0e0d-2efe-4721-8372-b2291af3df57', 'Muzaffer', '#1234 restoran bir müşteriyi banlayabilir mi? sürekli sorun ileten bir müşteriden sipariş gelmesini istemiyor restoran', '"2026-06-23T10:30:04.080Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('68410781-801d-453a-8133-431c85541212', 'Muzaffer', '#2 sipariş kuryeye teslim edildi,  1 yolda motor arıza yaptı, bu duruma fiyuu nun bir çözümü var mı? 2- çukura düştü ürünler dağıldı içecek döküldü . çözüm nedir?', '"2026-06-23T10:37:23.187Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('6eb83491-0509-4435-b43f-d134fd87a7b0', 'Muzaffer', '#2 restoran siparişi kuryeye teslim etti, kurye çıktıktan sonra ürünü eksik koyduğunu yanlış siparişi teslim ettiğini farketti, bize ulaşıp bu durumu aktardı, kuryenin geri dönüp almasını istiyor..', '"2026-06-23T11:18:39.271Z"'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO "qa_questions" ("id", "author_name", "question_text", "created_at") VALUES ('65b18dd8-0853-446e-8853-b45524bb75dd', 'muzaffer', '#2 müşteri sipariş verdi, evdeyken yanlışlıkla iş adresini seçti (uygulama uyarı yapıyor mu) , sipariş yanlış adrese gitti müşteri adreste yok. bu durumda ne yapıyoruz.', '"2026-06-23T15:27:31.466Z"'::jsonb) ON CONFLICT DO NOTHING;
